-- =====================================================================
-- DGR Office 1.0.0 - DEMO DATABASE (EVALUATION ONLY - never for real data
-- and never on a public server: the demo passwords are published).
-- Fictional "DEMO COMPANY (NOT REAL)" with placeholder GSTIN and bank,
-- clients, invoices, receipts, expenses, CRM leads, recruitment, payroll.
--
-- Import into an EMPTY database, point .env at it, run:
--      php spark key:generate
--      php spark dgr:install          (reports nothing pending)
-- Logins (password for all: Copper-Lantern-Field-31):
--   owner@demo.dgr.local (Super Admin, must set a new password at first sign-in)
--   accountant@, billing@, crm.manager@, telecaller1@, telecaller2@,
--   hr@, recruiter@, payroll@, employee@  (all @demo.dgr.local)
-- Demo bank/employee account numbers were encrypted with another key, so
-- only the masked last 4 digits show on your install. That is expected.
-- =====================================================================

-- DGR Office database backup
-- Database: dgr_demo_dump · Server: 8.0.46-0ubuntu0.24.04.4 · Created: 18-10-2026 07:04:34 IST
-- Restore: gunzip -c dgr-20261018-070434.sql.gz | mysql -u USER -p DATABASE   (into an EMPTY database)
-- Encrypted columns need the same encryption.key from .env to be readable.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+00:00';

DROP TABLE IF EXISTS `ai_access_grants`;
CREATE TABLE `ai_access_grants` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `capability` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token_id` int unsigned DEFAULT NULL,
  `record_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `record_id` bigint unsigned NOT NULL,
  `allowed_fields` json NOT NULL,
  `purpose` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requested_by` int unsigned DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_aag` (`capability`,`record_type`,`record_id`),
  KEY `fk_aag_token` (`token_id`),
  CONSTRAINT `fk_aag_cap` FOREIGN KEY (`capability`) REFERENCES `ai_capabilities` (`code`),
  CONSTRAINT `fk_aag_token` FOREIGN KEY (`token_id`) REFERENCES `ai_service_tokens` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ai_action_logs`;
CREATE TABLE `ai_action_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `occurred_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `capability` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `token_id` int unsigned DEFAULT NULL,
  `grant_id` bigint unsigned DEFAULT NULL,
  `actor_user_id` int unsigned DEFAULT NULL,
  `record_type` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `record_ids` json DEFAULT NULL,
  `field_names` json DEFAULT NULL COMMENT 'names only — never contents',
  `provider` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `outcome` enum('allowed','denied','error','completed','fallback') COLLATE utf8mb4_unicode_ci NOT NULL,
  `deny_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `http_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `input_tokens` int unsigned DEFAULT NULL,
  `output_tokens` int unsigned DEFAULT NULL,
  `cost_estimate` decimal(10,4) DEFAULT NULL,
  `duration_ms` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_aal_time` (`occurred_at`),
  KEY `idx_aal_cap` (`capability`,`outcome`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ai_capabilities`;
CREATE TABLE `ai_capabilities` (
  `code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '0',
  `allowed_fields` json NOT NULL,
  `scope_config` json DEFAULT NULL COMMENT 'e.g. allowlisted employee ids',
  `share_with_provider` tinyint(1) NOT NULL DEFAULT '0',
  `requires_consent` tinyint(1) NOT NULL DEFAULT '1',
  `rate_limit_per_hour` smallint unsigned NOT NULL DEFAULT '30',
  `monthly_cost_ceiling` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'USD, 0 = feature blocked',
  `retention_days` smallint unsigned NOT NULL DEFAULT '180',
  `updated_by` int unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
