DROP TABLE IF EXISTS `ai_cv_evaluations`;
CREATE TABLE `ai_cv_evaluations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint unsigned NOT NULL,
  `candidate_document_id` bigint unsigned DEFAULT NULL,
  `jd_version_id` int unsigned NOT NULL,
  `engine` enum('ai','rules') COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prompt_version` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('completed','unavailable','failed') COLLATE utf8mb4_unicode_ci NOT NULL,
  `fit_score` decimal(3,1) DEFAULT NULL,
  `category_scores` json DEFAULT NULL,
  `matched_requirements` json DEFAULT NULL,
  `unmet_requirements` json DEFAULT NULL,
  `unclear_requirements` json DEFAULT NULL,
  `interview_questions` json DEFAULT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `explanation` text COLLATE utf8mb4_unicode_ci,
  `confidence` enum('low','medium','high') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `injection_flags` json DEFAULT NULL,
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `input_tokens` int unsigned DEFAULT NULL,
  `output_tokens` int unsigned DEFAULT NULL,
  `cost_estimate` decimal(10,4) DEFAULT NULL,
  `grant_id` bigint unsigned DEFAULT NULL,
  `requested_by` int unsigned DEFAULT NULL,
  `hr_decision` enum('pending','accepted','overridden') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `hr_score` decimal(3,1) DEFAULT NULL,
  `hr_override_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewed_by` int unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ace_cand` (`candidate_id`,`created_at`),
  KEY `fk_ace_doc` (`candidate_document_id`),
  KEY `fk_ace_jdv` (`jd_version_id`),
  KEY `fk_ace_grant` (`grant_id`),
  CONSTRAINT `fk_ace_cand` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`),
  CONSTRAINT `fk_ace_doc` FOREIGN KEY (`candidate_document_id`) REFERENCES `candidate_documents` (`id`),
  CONSTRAINT `fk_ace_grant` FOREIGN KEY (`grant_id`) REFERENCES `ai_access_grants` (`id`),
  CONSTRAINT `fk_ace_jdv` FOREIGN KEY (`jd_version_id`) REFERENCES `job_description_versions` (`id`),
  CONSTRAINT `chk_ace_score` CHECK (((`fit_score` is null) or ((`fit_score` >= 0) and (`fit_score` <= 10))))
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
