DROP TABLE IF EXISTS `ai_service_tokens`;
CREATE TABLE `ai_service_tokens` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `service_account_id` int unsigned NOT NULL,
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token_hint` char(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `capabilities` json NOT NULL,
  `scope` json DEFAULT NULL COMMENT 'record allowlist e.g. {candidate_ids:[..]} or {employee_ids:[..], period:..}',
  `purpose` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `max_uses` int unsigned DEFAULT NULL,
  `use_count` int unsigned NOT NULL DEFAULT '0',
  `last_used_at` datetime DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `revoked_by` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ast` (`token_hash`),
  KEY `fk_ast_acc` (`service_account_id`),
  CONSTRAINT `fk_ast_acc` FOREIGN KEY (`service_account_id`) REFERENCES `ai_service_accounts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `app_settings`;
CREATE TABLE `app_settings` (
  `setting_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `setting_value` text COLLATE utf8mb4_unicode_ci,
  `value_type` enum('string','int','bool','json','decimal') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'string',
  `updated_by` int unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
