DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `att_date` date NOT NULL,
  `status` enum('present','absent','half_day','leave','holiday','week_off') COLLATE utf8mb4_unicode_ci NOT NULL,
  `leave_request_id` bigint unsigned DEFAULT NULL,
  `check_in_at` datetime DEFAULT NULL,
  `check_out_at` datetime DEFAULT NULL,
  `overtime_minutes` smallint unsigned NOT NULL DEFAULT '0',
  `source` enum('manual','self','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `remarks` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `corrected` tinyint(1) NOT NULL DEFAULT '0',
  `correction_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_att` (`employee_id`,`att_date`),
  KEY `idx_att_date` (`att_date`),
  KEY `fk_att_lr` (`leave_request_id`),
  CONSTRAINT `fk_att_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_att_lr` FOREIGN KEY (`leave_request_id`) REFERENCES `leave_requests` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=235 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
