  `bank_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `beneficiary_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_number_enc` text COLLATE utf8mb4_unicode_ci COMMENT 'encrypted',
  `account_last4` char(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ifsc` char(11) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `branch` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_type` enum('current','savings','od','cc','wallet','other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `upi_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cif_enc` text COLLATE utf8mb4_unicode_ci COMMENT 'encrypted; internal only, never printed/exported/sent to AI',
  `qr_asset_id` int unsigned DEFAULT NULL,
  `display_priority` smallint NOT NULL DEFAULT '100',
  `show_on_invoice` tinyint(1) NOT NULL DEFAULT '0',
  `is_default_on_invoice` tinyint(1) NOT NULL DEFAULT '0',
  `print_approved_by` int unsigned DEFAULT NULL COMMENT 'required before a personal account can be printed',
  `print_approved_at` datetime DEFAULT NULL,
  `ledger_account_id` int unsigned NOT NULL,
  `opening_balance` decimal(15,2) NOT NULL DEFAULT '0.00',
  `opening_date` date DEFAULT NULL,
  `requires_review` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'flag receipts for reconciliation review',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bca_code` (`code`),
  UNIQUE KEY `uq_bca_ledger` (`ledger_account_id`),
  KEY `fk_bca_qr` (`qr_asset_id`),
  CONSTRAINT `fk_bca_ledger` FOREIGN KEY (`ledger_account_id`) REFERENCES `ledger_accounts` (`id`),
  CONSTRAINT `fk_bca_qr` FOREIGN KEY (`qr_asset_id`) REFERENCES `branding_assets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
