DROP TABLE IF EXISTS `billing_share_links`;
CREATE TABLE `billing_share_links` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `access_count` int unsigned NOT NULL DEFAULT '0',
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bsl` (`token_hash`),
  KEY `fk_bsl_doc` (`document_id`),
  CONSTRAINT `fk_bsl_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `billing_taxes`;
CREATE TABLE `billing_taxes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `tax_type` enum('CGST','SGST','UTGST','IGST','CESS') COLLATE utf8mb4_unicode_ci NOT NULL,
  `rate` decimal(6,3) NOT NULL,
  `taxable_value` decimal(15,2) NOT NULL,
  `tax_amount` decimal(15,2) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bt` (`document_id`,`tax_type`,`rate`),
  CONSTRAINT `fk_bt_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
