DROP TABLE IF EXISTS `company_settings`;
CREATE TABLE `company_settings` (
  `id` tinyint unsigned NOT NULL DEFAULT '1',
  `legal_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trade_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tagline` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gstin` char(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pan` char(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gst_registration_type` enum('regular','composition','unregistered') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
  `state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reg_address_line1` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reg_address_line2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reg_city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reg_district` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reg_pincode` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_address_same` tinyint(1) NOT NULL DEFAULT '1',
  `bill_address_line1` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_address_line2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_district` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bill_pincode` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alt_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alt_email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `website` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_category` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contact_persons` json DEFAULT NULL,
  `einvoice_applicable` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'decision recorded by owner/accountant',
  `lut_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lut_valid_till` date DEFAULT NULL,
  `invoice_footer` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoice_terms` text COLLATE utf8mb4_unicode_ci,
  `legal_disclaimer` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fy_start_month` tinyint unsigned NOT NULL DEFAULT '4',
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `timezone` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Asia/Kolkata',
  `default_payment_terms_days` smallint unsigned NOT NULL DEFAULT '15',
  `rounding_policy` enum('none','nearest_rupee') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'nearest_rupee',
  `default_price_mode` enum('exclusive','inclusive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'exclusive',
  `default_template_id` int unsigned DEFAULT NULL,
  `brand_primary` varchar(9) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#111111',
  `brand_accent` varchar(9) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#B08D57',
  `setup_steps` json DEFAULT NULL COMMENT 'wizard completion status',
  `setup_completed_at` datetime DEFAULT NULL,
  `profile_version` int unsigned NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_cs_state` (`state_code`),
  KEY `fk_cs_bstate` (`bill_state_code`),
  KEY `fk_cs_tpl` (`default_template_id`),
  CONSTRAINT `fk_cs_bstate` FOREIGN KEY (`bill_state_code`) REFERENCES `states` (`code`),
  CONSTRAINT `fk_cs_state` FOREIGN KEY (`state_code`) REFERENCES `states` (`code`),
  CONSTRAINT `fk_cs_tpl` FOREIGN KEY (`default_template_id`) REFERENCES `document_templates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_cs_singleton` CHECK ((`id` = 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
