DROP TABLE IF EXISTS `contact_files`;
CREATE TABLE `contact_files` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `contact_id` bigint unsigned NOT NULL,
  `stored_file_id` bigint unsigned NOT NULL,
  `label` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_cf_contact` (`contact_id`),
  KEY `fk_cf_file` (`stored_file_id`),
  CONSTRAINT `fk_cf_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cf_file` FOREIGN KEY (`stored_file_id`) REFERENCES `stored_files` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contact_merges`;
CREATE TABLE `contact_merges` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_contact_id` bigint unsigned NOT NULL,
  `target_contact_id` bigint unsigned NOT NULL,
  `snapshot` json NOT NULL,
  `merged_by` int unsigned DEFAULT NULL,
  `merged_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_cm_src` (`source_contact_id`),
  KEY `fk_cm_tgt` (`target_contact_id`),
  CONSTRAINT `fk_cm_src` FOREIGN KEY (`source_contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_cm_tgt` FOREIGN KEY (`target_contact_id`) REFERENCES `contacts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contact_people`;
CREATE TABLE `contact_people` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `contact_id` bigint unsigned NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `designation` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_cp_contact` (`contact_id`),
  CONSTRAINT `fk_cp_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `contacts`;
CREATE TABLE `contacts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `contact_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_customer` tinyint(1) NOT NULL DEFAULT '1',
  `is_vendor` tinyint(1) NOT NULL DEFAULT '0',
  `is_prospect` tinyint(1) NOT NULL DEFAULT '0',
  `entity_kind` enum('company','individual') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'company',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `legal_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contact_person` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_normalized` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alt_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `whatsapp` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gstin` char(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gst_registration_type` enum('registered','unregistered','composition','consumer','sez','overseas','uin') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unregistered',
  `pan` char(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state_code` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state_source` enum('gstin','address','manual') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pincode` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `industry` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `credit_days` smallint unsigned DEFAULT NULL,
  `credit_limit` decimal(15,2) DEFAULT NULL,
  `opening_balance` decimal(15,2) NOT NULL DEFAULT '0.00',
  `opening_balance_type` enum('dr','cr') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'dr',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `dnd` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `merged_into_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_contact_code` (`contact_code`),
  KEY `idx_contact_phone` (`phone_normalized`),
  KEY `idx_contact_gstin` (`gstin`),
  KEY `idx_contact_name` (`name`),
  KEY `idx_contact_flags` (`is_customer`,`is_vendor`,`is_active`),
  KEY `fk_contact_state` (`state_code`),
  KEY `fk_contact_merged` (`merged_into_id`),
  CONSTRAINT `fk_contact_merged` FOREIGN KEY (`merged_into_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_contact_state` FOREIGN KEY (`state_code`) REFERENCES `states` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
