DROP TABLE IF EXISTS `credit_debit_note_links`;
CREATE TABLE `credit_debit_note_links` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `note_document_id` bigint unsigned NOT NULL,
  `original_document_id` bigint unsigned NOT NULL,
  `reason_code` enum('price_revision','service_deficiency','post_sale_discount','excess_billing','short_billing','cancellation','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason_text` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cdnl` (`note_document_id`),
  KEY `fk_cdnl_orig` (`original_document_id`),
  CONSTRAINT `fk_cdnl_note` FOREIGN KEY (`note_document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_cdnl_orig` FOREIGN KEY (`original_document_id`) REFERENCES `billing_documents` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_daily_targets`;
CREATE TABLE `crm_daily_targets` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `effective_from` date NOT NULL,
  `calls_per_day` smallint unsigned NOT NULL DEFAULT '60',
  `connected_per_day` smallint unsigned NOT NULL DEFAULT '20',
  `followups_per_day` smallint unsigned NOT NULL DEFAULT '15',
  `meetings_per_week` smallint unsigned NOT NULL DEFAULT '5',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cdt` (`user_id`,`effective_from`),
  CONSTRAINT `fk_cdt_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `crm_stages`;
CREATE TABLE `crm_stages` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` smallint NOT NULL DEFAULT '0',
  `is_won` tinyint(1) NOT NULL DEFAULT '0',
  `is_lost` tinyint(1) NOT NULL DEFAULT '0',
  `is_closed` tinyint(1) NOT NULL DEFAULT '0',
  `is_dnd` tinyint(1) NOT NULL DEFAULT '0',
  `color` varchar(9) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#6c757d',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stage_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
