DROP TABLE IF EXISTS `google_sync_jobs`;
CREATE TABLE `google_sync_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint unsigned NOT NULL,
  `worksheet` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` enum('upsert','delete') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'upsert',
  `payload_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','processing','done','failed','dead') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attempts` smallint unsigned NOT NULL DEFAULT '0',
  `max_attempts` smallint unsigned NOT NULL DEFAULT '8',
  `next_attempt_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `locked_at` datetime DEFAULT NULL,
  `locked_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remote_row_ref` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_success_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gsj_idem` (`idempotency_key`),
  KEY `idx_gsj_due` (`status`,`next_attempt_at`),
  KEY `idx_gsj_entity` (`entity_type`,`entity_id`,`worksheet`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
