DROP TABLE IF EXISTS `interviews`;
CREATE TABLE `interviews` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint unsigned NOT NULL,
  `round_no` smallint unsigned NOT NULL DEFAULT '1',
  `interview_type` enum('hr_screening','technical','managerial','group_discussion','assignment','final') COLLATE utf8mb4_unicode_ci NOT NULL,
  `scheduled_at` datetime NOT NULL,
  `duration_minutes` smallint unsigned NOT NULL DEFAULT '30',
  `mode` enum('in_person','phone','video') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_person',
  `location_or_link` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `interviewer_id` int unsigned NOT NULL,
  `status` enum('scheduled','completed','cancelled','no_show') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `result` enum('pending','pass','fail','hold') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `overall_rating` tinyint unsigned DEFAULT NULL,
  `feedback` text COLLATE utf8mb4_unicode_ci,
  `attachment_file_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_int_cand` (`candidate_id`),
  KEY `idx_int_user` (`interviewer_id`,`scheduled_at`),
  KEY `fk_int_file` (`attachment_file_id`),
  CONSTRAINT `fk_int_cand` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`),
  CONSTRAINT `fk_int_file` FOREIGN KEY (`attachment_file_id`) REFERENCES `stored_files` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_int_user` FOREIGN KEY (`interviewer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_int_rating` CHECK (((`overall_rating` is null) or (`overall_rating` between 1 and 5)))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
