DROP TABLE IF EXISTS `leads`;
CREATE TABLE `leads` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact_person` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mobile_normalized` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alt_mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pincode` char(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `area` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `industry` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `services_interested` json DEFAULT NULL,
  `source_id` int unsigned DEFAULT NULL,
  `campaign` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assigned_to` int unsigned DEFAULT NULL,
  `priority` enum('low','medium','high','hot') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `stage_id` int unsigned NOT NULL,
  `expected_value` decimal(15,2) DEFAULT NULL,
  `next_followup_at` datetime DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `last_action` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_action_at` datetime DEFAULT NULL,
  `call_attempts` int unsigned NOT NULL DEFAULT '0',
  `connected_calls` int unsigned NOT NULL DEFAULT '0',
  `lost_reason_id` int unsigned DEFAULT NULL,
  `consent_status` enum('unknown','consented','withdrawn') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `dnd` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'do not call',
  `dnd_marked_at` datetime DEFAULT NULL,
  `contact_id` bigint unsigned DEFAULT NULL COMMENT 'set on conversion',
  `converted_at` datetime DEFAULT NULL,
  `retention_until` date DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lead_code` (`lead_code`),
  KEY `idx_lead_mobile` (`mobile_normalized`),
  KEY `idx_lead_assigned` (`assigned_to`,`next_followup_at`),
  KEY `idx_lead_stage` (`stage_id`),
  KEY `idx_lead_created` (`created_at`),
  KEY `fk_lead_source` (`source_id`),
  KEY `fk_lead_lost` (`lost_reason_id`),
  KEY `fk_lead_contact` (`contact_id`),
  CONSTRAINT `fk_lead_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_lead_lost` FOREIGN KEY (`lost_reason_id`) REFERENCES `lost_reasons` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_lead_source` FOREIGN KEY (`source_id`) REFERENCES `lead_sources` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_lead_stage` FOREIGN KEY (`stage_id`) REFERENCES `crm_stages` (`id`),
  CONSTRAINT `fk_lead_user` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
