DROP TABLE IF EXISTS `meetings`;
CREATE TABLE `meetings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `lead_id` bigint unsigned DEFAULT NULL,
  `contact_id` bigint unsigned DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `meeting_at` datetime NOT NULL,
  `duration_minutes` smallint unsigned NOT NULL DEFAULT '30',
  `mode` enum('in_person','phone','video') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_person',
  `location_or_link` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organizer_id` int unsigned NOT NULL,
  `attendee_ids` json DEFAULT NULL,
  `status` enum('scheduled','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `outcome` text COLLATE utf8mb4_unicode_ci,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_mtg_org` (`organizer_id`,`meeting_at`),
  KEY `idx_mtg_lead` (`lead_id`),
  KEY `fk_mtg_contact` (`contact_id`),
  CONSTRAINT `fk_mtg_contact` FOREIGN KEY (`contact_id`) REFERENCES `contacts` (`id`),
  CONSTRAINT `fk_mtg_lead` FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`),
  CONSTRAINT `fk_mtg_user` FOREIGN KEY (`organizer_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

