DROP TABLE IF EXISTS `payment_allocations`;
CREATE TABLE `payment_allocations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` bigint unsigned NOT NULL,
  `document_id` bigint unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `allocated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `allocated_by` int unsigned DEFAULT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL COMMENT 'set when applied from advances after the receipt',
  `reversed_at` datetime DEFAULT NULL,
  `reversed_by` int unsigned DEFAULT NULL,
  `reversal_journal_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pa_doc` (`document_id`),
  KEY `idx_pa_receipt` (`receipt_id`),
  CONSTRAINT `fk_pa_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_pa_receipt` FOREIGN KEY (`receipt_id`) REFERENCES `payment_receipts` (`id`),
  CONSTRAINT `chk_pa_amount` CHECK ((`amount` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
