DROP TABLE IF EXISTS `payroll_payments`;
CREATE TABLE `payroll_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `payroll_run_id` int unsigned NOT NULL,
  `payroll_item_id` bigint unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `mode` enum('cash','upi','bank_transfer','neft','rtgs','imps','cheque','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `bank_cash_account_id` int unsigned NOT NULL,
  `reference_no` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reconciliation_status` enum('unmatched','partial','matched') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unmatched',
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pp_item` (`payroll_item_id`),
  KEY `fk_pp_run` (`payroll_run_id`),
  KEY `fk_pp_bca` (`bank_cash_account_id`),
  KEY `fk_pp_je` (`journal_entry_id`),
  CONSTRAINT `fk_pp_bca` FOREIGN KEY (`bank_cash_account_id`) REFERENCES `bank_cash_accounts` (`id`),
  CONSTRAINT `fk_pp_item` FOREIGN KEY (`payroll_item_id`) REFERENCES `payroll_items` (`id`),
  CONSTRAINT `fk_pp_je` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`),
  CONSTRAINT `fk_pp_run` FOREIGN KEY (`payroll_run_id`) REFERENCES `payroll_runs` (`id`),
  CONSTRAINT `chk_pp` CHECK ((`amount` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
