DROP TABLE IF EXISTS `reconciliation_matches`;
CREATE TABLE `reconciliation_matches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bank_import_line_id` bigint unsigned NOT NULL,
  `match_type` enum('receipt','transfer_in','transfer_out','expense_payment','salary_payment','refund','journal') COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_id` bigint unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `confidence` decimal(5,2) NOT NULL DEFAULT '0.00',
  `status` enum('suggested','confirmed','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'suggested',
  `confirmed_by` int unsigned DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rm` (`bank_import_line_id`,`match_type`,`match_id`),
  KEY `idx_rm_target` (`match_type`,`match_id`,`status`),
  CONSTRAINT `fk_rm_line` FOREIGN KEY (`bank_import_line_id`) REFERENCES `bank_import_lines` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `recruitment_events`;
CREATE TABLE `recruitment_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint unsigned NOT NULL,
  `event_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `actor_id` int unsigned DEFAULT NULL,
  `source` enum('manual','system','ai_proposed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `proposal_status` enum('na','proposed','accepted','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'na',
  `ai_evaluation_id` bigint unsigned DEFAULT NULL,
  `ref_type` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ref_id` bigint unsigned DEFAULT NULL,
  `occurred_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_re_cand` (`candidate_id`,`occurred_at`),
  KEY `fk_re_ace` (`ai_evaluation_id`),
  CONSTRAINT `fk_re_ace` FOREIGN KEY (`ai_evaluation_id`) REFERENCES `ai_cv_evaluations` (`id`),
  CONSTRAINT `fk_re_cand` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
