DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_super` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'implicitly holds every permission',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'starter role (still editable, not deletable if super)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_roles_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `roles` VALUES
('1','super_admin','Owner / Super Admin','All modules, approvals and permission management. Privileged actions are logged.','1','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('2','accountant','Accountant','Billing, finance, bank, GST reports. No CRM lead lists or candidate CVs by default.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('3','billing_operator','Billing Operator','Creates invoice/cash memo drafts for allowed customers. No revenue totals, bank, GST dashboards, CRM, HR. Finalize/print individually assignable.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('4','crm_manager','CRM Manager','All CRM data, assignments, team performance and Sheets sync status. No bank details or salaries.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('5','telecaller','Telecaller','Own assigned leads, calls, follow-ups, meetings, visits, tasks and own stats only.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('6','sales_executive','Sales Executive','Assigned leads, visits, meetings and quotations.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('7','hr_manager','HR Manager','Recruitment, employees, attendance, leave, incentives and payroll.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('8','hr_recruiter','HR Recruiter','JDs, assigned applicants, interviews, candidate timeline and scoped AI CV review. No finance, CRM or salary.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('9','payroll_manager','Payroll Manager','Attendance, approved incentives, payroll calculation and payslips. No billing/CRM.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('10','employee','Employee','Own attendance, leaves, payslips and assigned tasks only.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL),
('11','auditor','Auditor (Read Only)','Time-limited read-only access to selected registers and audit trails. Assign with an expiry date.','0','1','1',NULL,NULL,'2026-10-18 07:04:25',NULL);

