DROP TABLE IF EXISTS `salary_structures`;
CREATE TABLE `salary_structures` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `effective_from` date NOT NULL,
  `salary_type` enum('monthly','daily') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'monthly',
  `ctc_annual` decimal(12,2) DEFAULT NULL,
  `monthly_gross` decimal(12,2) NOT NULL COMMENT 'fixed monthly pay (or daily rate when salary_type=daily)',
  `proration_basis` enum('calendar_days','fixed_30','working_days') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'calendar_days',
  `overtime_rate_per_hour` decimal(10,2) DEFAULT NULL,
  `pf_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `esi_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `pt_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `tds_monthly` decimal(10,2) NOT NULL DEFAULT '0.00',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ss` (`employee_id`,`effective_from`),
  CONSTRAINT `fk_ss_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `chk_ss_gross` CHECK ((`monthly_gross` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
