DROP TABLE IF EXISTS `saved_views`;
CREATE TABLE `saved_views` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL,
  `module` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `filters` json DEFAULT NULL,
  `columns` json DEFAULT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sv` (`user_id`,`module`),
  CONSTRAINT `fk_sv_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `sac_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Service',
  `default_rate` decimal(15,2) NOT NULL DEFAULT '0.00',
  `default_tax_rate_id` int unsigned DEFAULT NULL,
  `default_tax_treatment` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'regular',
  `pos_rule` enum('default','review_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT 'special place-of-supply rules need human review',
  `is_recurring_type` tinyint(1) NOT NULL DEFAULT '0',
  `review_status` enum('suggested','accountant_reviewed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'suggested',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_svc_code` (`code`),
  KEY `fk_svc_tax` (`default_tax_rate_id`),
  KEY `fk_svc_treat` (`default_tax_treatment`),
  CONSTRAINT `fk_svc_tax` FOREIGN KEY (`default_tax_rate_id`) REFERENCES `tax_rates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_svc_treat` FOREIGN KEY (`default_tax_treatment`) REFERENCES `tax_treatments` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
