DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `class` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci,
  `type` varchar(31) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'string',
  `context` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `signature_policies`;
CREATE TABLE `signature_policies` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `role_id` int unsigned DEFAULT NULL,
  `user_id` int unsigned DEFAULT NULL,
  `doc_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `allowed` tinyint(1) NOT NULL DEFAULT '0',
  `approved_by` int unsigned DEFAULT NULL COMMENT 'owner approval',
  `approved_at` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sp` (`role_id`,`user_id`,`doc_type`),
  KEY `fk_sp_user` (`user_id`),
  CONSTRAINT `fk_sp_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`),
  CONSTRAINT `fk_sp_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_sp_subject` CHECK (((`role_id` is null) <> (`user_id` is null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `signature_usage_log`;
CREATE TABLE `signature_usage_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `assets` json NOT NULL COMMENT 'asset ids + versions used',
  `policy_id` int unsigned DEFAULT NULL,
  `used_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sul_doc` (`document_id`),
  KEY `fk_sul_user` (`user_id`),
  CONSTRAINT `fk_sul_doc` FOREIGN KEY (`document_id`) REFERENCES `billing_documents` (`id`),
  CONSTRAINT `fk_sul_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `states`;
CREATE TABLE `states` (
  `code` char(2) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'GST state code',
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alpha_code` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_ut` tinyint(1) NOT NULL DEFAULT '0',
  `uses_utgst` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'UT without legislature → CGST+UTGST',
  `is_special` tinyint(1) NOT NULL DEFAULT '0' COMMENT '96 Other Country / 97 Other Territory',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
