DROP TABLE IF EXISTS `statutory_configs`;
CREATE TABLE `statutory_configs` (
  `code` enum('PF','ESI','PT','TDS','LWF') COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '0',
  `employee_rate` decimal(6,3) DEFAULT NULL,
  `employer_rate` decimal(6,3) DEFAULT NULL,
  `wage_ceiling` decimal(12,2) DEFAULT NULL,
