DROP TABLE IF EXISTS `task_reminders`;
CREATE TABLE `task_reminders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` enum('task','followup','visit','meeting','interview','recurring_invoice','recurring_expense') COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` bigint unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `remind_at` datetime NOT NULL,
  `channel` enum('in_app','email') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_app',
  `sent_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tr` (`entity_type`,`entity_id`,`user_id`,`remind_at`,`channel`),
  KEY `idx_tr_due` (`sent_at`,`remind_at`),
  KEY `fk_tr_user` (`user_id`),
  CONSTRAINT `fk_tr_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
