DROP TABLE IF EXISTS `weekly_off_rules`;
CREATE TABLE `weekly_off_rules` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `weekday` tinyint unsigned NOT NULL COMMENT '0=Sunday … 6=Saturday',
  `week_numbers` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = every week; e.g. 2,4 = 2nd & 4th',
  `effective_from` date NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  CONSTRAINT `chk_wor` CHECK ((`weekday` between 0 and 6))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `weekly_off_rules` VALUES
